// Confessor of Desires / Исповедник Желаний (Дар Слаанеш, wdbc-1rno).
// Книга: цель проходит тест W-60 (как от психосилы) или честно отвечает на
// вопрос о сокровенных желаниях, не осознавая влияния. Прошедший тест
// осознаёт голос и получает иммунитет к нему на 6 дней. Сам факт "спросить о
// желаниях" — реплика за столом, движку сверять не с чем: кнопка начинается
// с того, что цель уже выбрана обычным таргетингом Foundry.
const targetDoc = game.user.targets?.first?.() ?? [...(game.user.targets ?? [])][0];
const targetActor = (targetDoc?.document ?? targetDoc)?.actor;
if (!targetActor) {
  ui.notifications?.warn("Исповедник Желаний: выберите одну цель.");
} else {
  const DAY_SECONDS = 86400; // constants/imperial-calendar.mjs::SECONDS_PER_DAY — скрипты не импортируют модули
  const immuneUntil = Number(targetActor.getFlag("warhammer-dbc", "confessorOfDesiresImmuneUntil")) || 0;
  if (game.time.worldTime < immuneUntil) {
    const daysLeft = Math.ceil((immuneUntil - game.time.worldTime) / DAY_SECONDS);
    ui.notifications?.info(`Исповедник Желаний: ${targetActor.name} уже осознаёт влияние голоса — иммунитет ещё ${daysLeft} дн.`);
  } else {
    const wp = Number(targetActor.system?.characteristics?.wp?.total) || 0;
    const threshold = wp - 60;
    const roll = await new Roll("1d100").evaluate();
    const success = roll.total <= threshold;
    let line;
    if (success) {
      await targetActor.setFlag("warhammer-dbc", "confessorOfDesiresImmuneUntil", game.time.worldTime + 6 * DAY_SECONDS);
      line = `<b>Успех</b> — ${targetActor.name} осознаёт противоестественное влияние и получает иммунитет на 6 дней.`;
    } else {
      line = `<b>Провал</b> — честно отвечает на вопрос о сокровенных желаниях, не осознавая влияния (считает, что рассказал добровольно).`;
    }
    await ChatMessage.create(ChatMessage.applyRollMode({
      speaker,
      content: `<div class="wh-roll-result">
        <div class="roll-header">Исповедник Желаний — ${actor.name} → ${targetActor.name}</div>
        <div class="roll-threshold">Тест W-60 — порог <b>${threshold}</b> (W ${wp}), бросок <b>${roll.total}</b></div>
        <div class="roll-threshold">${line}</div>
      </div>`,
      rolls: [roll]
    }, game.settings.get("core", "rollMode")));
  }
}
